Given an array arr[] of integers, find the next smaller element of the next greater element for each element in the array.Note: Elements for which no greater element exists or no smaller of greater element exist, print -1.Examples: Input : arr[] = [5, 1, 9, 2, 5, 1, 7]Output:  [2, 2, -1, 1, -1, -1, -1]Explanation: Input  : arr[] = [4, 8, 2, 1, 9, 5, 6, 3]Output :  [2,  5,  5,  5, -1,  3, -1, -1]      Table of ContentUsing Two For Loops - O(n) Time and O(1) SpaceUsing Monotonic Stack - O( n) Time and O(1) SpaceUsing Two For Loops - O(n) Time and O(1) SpaceA simple approach is to iterate through each element of the array. For every element, first find its next greater element on the right, and then determine the next smaller element to the right of that greater element.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
using namespace std;
//Driver Code Ends


vector<int> nextSmallerOfNextGreater(int arr[], int n)
{
    vector<int> result(n, -1);

    // For 1st n-1 elements of vector
    for (int i = 0; i < n - 1; i++)
    {

        int temp = arr[i];
        int next = -1;
        int ans = -1;

        // find the next greater
        for (int j = i + 1; j < n; j++)
        {
            if (arr[j] > temp)
            {
                next = j;
                break;
            }
        }

        if (next == -1)
        {
            result[i] = -1;
        }
        else
        {
            // find the next smaller of the next
            for (int j = next + 1; j < n; j++)
            {
                if (arr[j] < arr[next])
                {
                    ans = j;
                    break;
                }
            }
            if (ans == -1)
            {
                result[i] = -1;
            }
            else
            {
                result[i] = arr[ans];
            }
        }
    }

    return result;
}


