{
    int arr[] = {5, 1, 9, 2, 5, 1, 7};
    int n = sizeof(arr) / sizeof(arr[0]);
    vector<int> result = nextSmallerOfNextGreater(arr, n);
    for (int x : result)
    {
        cout << x << " ";
    }
    cout << endl;
    return 0;
}
