    //Driver Code Starts
#include <iostream>
#include <stack>
#include <vector>
using namespace std;

//Driver Code Ends

vector<int> nextSmallerOfNextGreater(int arr[], int n)
{
    // store index of next greater element
    vector<int> nge(n, -1); 

    // store value of next smaller element
    vector<int> nse(n, -1); 
    stack<int> st;
    vector<int> result(n, -1);

    // Find Next Greater Element index for each element
    for (int i = n - 1; i >= 0; i--)
    {
        while (!st.empty() && arr[st.top()] <= arr[i])
            st.pop();

        if (!st.empty())
            nge[i] = st.top();

        st.push(i);
    }

    // clear stack for next computation
    while (!st.empty())
        st.pop();

    // Find Next Smaller Element value for each element
    for (int i = n - 1; i >= 0; i--)
    {
        while (!st.empty() && arr[st.top()] >= arr[i])
            st.pop();

        if (!st.empty())
            nse[i] = arr[st.top()];

        st.push(i);
    }

    // Step 3: Combine results
    for (int i = 0; i < n; i++)
    {

        if (nge[i] == -1)
            continue;
        else
            result[i] = nse[nge[i]];
    }
    return result;
}


